mapper.select:
SELECT A.order_type, /*指令类型*/
       A.is_book, /*是否随交易入账*/
       A.para_code, /*系统参数Code*/
       A.param_value /*系统参数Value*/
  FROM STL_ORDERS_MAPPING A
 WHERE A.busi_type = #{busiType}
   AND A.trade_ps = #{ps}
   AND A.finprod_type = #{finprodType}


   		AND A.inv_aim  = #{invAim}

select t.* from(
	SELECT A.PROFIT_TYPE, row_number() over() as rownum                   
	FROM PTL_PORTFOLIO A                   
	WHERE A.PORTFOLIO_ID =  #{portfolidId,jdbcType=VARCHAR}

) t where t.rownum = 1
